function groupBy(list, keyFn) {
  var groups = {};
  list.forEach(function (item) {
    var key = keyFn(item);
    if (!groups[key]) {
      groups[key] = [];
    }
    groups[key].push(item);
  });
  return groups;
}

var nums = [1, 2, 3, 4, 5, 6];
console.log(groupBy(nums, function (n) {
  return n % 2 === 0 ? "even" : "odd";
}));
